from pager import page
def ref(items, n, size=10): return items[n*size:(n+1)*size]
for N in (0, 1, 9, 10, 11, 25, 30, 47):
    xs = list(range(100, 100+N))
    for size in (1, 3, 5, 10, 7):
        for n in range(0, N//size + 3):
            assert page(xs, n, size) == ref(xs, n, size), (N, n, size)
    for n in range(4):
        assert page(xs, n) == ref(xs, n), (N, n)
assert page(list("abcdefg"), 1, 3) == list("def")
print("ok")
